79	                  seq: seqReq.result as number | undefined,
80	                });
81	              };
82	              tx.onerror = () => reject(tx.error);
83	            } catch (err) {
84	              reject(err);
85	            }
86	          };
87	        }
88	      );
89	    },
90	    { nodeId }
91	  );
92	}
