const raw = fs.readFileSync(SC + 'plan-pre-hooks.json', 'utf8');

// Escape raw control chars (< 0x20) ONLY when inside a JSON string literal.
let out = '';
let inStr = false;
let esc = false;
for (let i = 0; i < raw.length; i++) {
  const ch = raw[i];
  const code = raw.charCodeAt(i);
  if (inStr) {
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\') { out += ch; esc = true; continue; }
    if (ch === '"') { out += ch; inStr = false; continue; }
    if (code < 0x20) {
      if (ch === '\n') out += '\\n';
      else if (ch === '\t') out += '\\t';
      else if (ch === '\r') out += '\\r';
      else out += '\\u' + code.toString(16).padStart(4, '0');
      continue;
    }
    out += ch;
  } else {
    if (ch === '"') { inStr = true; out += ch; continue; }
    out += ch;
  }
}

let o;
