const fs = require('fs');
const ROOT = '/Users/myankelev/Code/random/cipher-box';
const pkgs = ['crypto', 'core', 'api-client', 'sdk-core', 'sdk'];

// 1. Add a test-inclusive `typecheck` script to each package (tsconfig.json includes tests).
for (const p of pkgs) {
  const f = `${ROOT}/packages/${p}/package.json`;
  const j = JSON.parse(fs.readFileSync(f, 'utf8'));
  j.scripts = j.scripts || {};
  // Insert `typecheck` immediately after `build` for readability.
  const entries = Object.entries(j.scripts).filter(([k]) => k !== 'typecheck');
  const rebuilt = {};
  for (const [k, v] of entries) {
    rebuilt[k] = v;
    if (k === 'build') rebuilt.typecheck = 'tsc --noEmit';
  }
  if (!rebuilt.typecheck) rebuilt.typecheck = 'tsc --noEmit';
  j.scripts = rebuilt;
  fs.writeFileSync(f, JSON.stringify(j, null, 2) + '\n');
  console.log(`updated packages/${p}/package.json (typecheck: tsc --noEmit)`);
}

// 2. Root: build first (existing), then a test-inclusive typecheck pass per package.
const rf = `${ROOT}/package.json`;
const rj = JSON.parse(fs.readFileSync(rf, 'utf8'));
const builds = [
  'pnpm --filter @cipherbox/crypto build',
  'pnpm --filter @cipherbox/core build',
  'pnpm --filter @cipherbox/api-client build',
  'pnpm --filter @cipherbox/sdk-core build',
  'pnpm --filter @cipherbox/sdk build',
  'pnpm --filter @cipherbox/web exec tsc -b',
  'tsc -p tsconfig.scripts.json --noEmit',
];
// Test-inclusive typecheck runs AFTER builds so cross-package types resolve from dist.
const testTypechecks = pkgs.map((p) => `pnpm --filter @cipherbox/${p} run typecheck`);
rj.scripts.typecheck = [...builds, ...testTypechecks].join(' && ');
fs.writeFileSync(rf, JSON.stringify(rj, null, 2) + '\n');
console.log('updated root package.json typecheck (build-first, then test-inclusive typecheck per package)');
console.log('\nNEW ROOT typecheck:\n' + rj.scripts.typecheck);

