455	   * descended into further.
456	   *
457	   * Bounded to `UNENROLL_COLLECT_CONCURRENCY` concurrent hops (T-68.1-02-01).
458	   * Zeroes every minted childReadKey; never zeroes `nodeReadKey` (caller-owned, D-09).
459	   */
460	  private async collectDescendantIpnsNames(
461	    nodeReadKey: Uint8Array,
462	    nodeChildren: SealedChildRef[]
463	  ): Promise<string[]> {
464	    const limit = pLimit(UNENROLL_COLLECT_CONCURRENCY);
465	    const results = await Promise.all(
466	      nodeChildren.map((childRef) =>
467	        limit(async (): Promise<string[]> => {
468	          try {
469	            const childResolved = await this.resolvePublishedNode(childRef.ipnsName);
470	            if (!childResolved) return [childRef.ipnsName];
471	            if (
472	              childResolved.published.kind !== 'folder' &&
473	              childResolved.published.kind !== 'root'
474	            ) {
475	              return [childRef.ipnsName];
476	            }
477	
478	            let childReadKey: Uint8Array | null = null;
479	            try {
480	              childReadKey = await unsealChildReadKey(
481	                childRef.readKeySealed,
482	                nodeReadKey,
483	                childResolved.published.id,
484	                childResolved.published.kind,
485	                childRef.generation
486	              );
487	              const childNode = await unsealNode(childResolved.published, childReadKey);
488	              const nested = await this.collectDescendantIpnsNames(
489	                childReadKey,
490	                childNode.children ?? []
491	              );
492	              return [childRef.ipnsName, ...nested];
493	            } finally {
494	              childReadKey?.fill(0);
495	            }
496	          } catch (err) {
497	            console.warn(
498	              `[CipherBox] subtree collect: unreadable descendant ${childRef.ipnsName}:`,
499	              err
500	            );
501	            return [childRef.ipnsName];
502	          }
503	        })
504	      )
505	    );
506	    return results.flat();
507	  }
508	
509	  /**
510	   * Extract IPNS names from a removed SealedChildRef (file or folder subtree).
511	   *
512	   * Resolves the item's own PublishedNode to learn its plaintext id/kind, then
513	   * (for a folder/root) recovers its readKey from `item.readKeySealed` under
514	   * `parentReadKey` and walks its descendants. A file leaf contributes only
515	   * its own ipnsName. Best-effort (T-68.1-02-01): an unresolvable/unreadable
516	   * item still contributes its own ipnsName so unenroll/unpin proceeds.
517	   *
518	   * @param parentReadKey - readKey of the folder `item` was just removed from
519	   *   (caller-owned — NOT zeroed here, D-09).
520	   */
521	  private async collectRemovedItemIpnsNames(
522	    item: SealedChildRef,
523	    parentReadKey: Uint8Array
524	  ): Promise<string[]> {
525	    try {
526	      const resolved = await this.resolvePublishedNode(item.ipnsName);
527	      if (!resolved) return [item.ipnsName];
528	      if (resolved.published.kind !== 'folder' && resolved.published.kind !== 'root') {
529	        return [item.ipnsName];
530	      }
531	
532	      let itemReadKey: Uint8Array | null = null;
533	      try {
534	        itemReadKey = await unsealChildReadKey(
535	          item.readKeySealed,
536	          parentReadKey,
537	          resolved.published.id,
538	          resolved.published.kind,
539	          item.generation
